      SUBROUTINE SPESHLCC     HANDLES SPECIAL PARAMETERS (TYPE CODE 16)CC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BETAC.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17B.CIN'      INCLUDE 'ISEEDX.CIN'CC     LOCAL VARIABLESC      EXTERNAL        IDATAC      J = NPARS      IADR = I + 2    5 NVARY = TIE(IADR)      IF (NVARY .EQ. 100) THEN        IADR = IDATA(IADR)        GO TO 5      ENDIFC      GO TO ( 10, 20, 30, 40, 40, 60, 70, 80, 90,100,     1       110,120,130,140,150,160,160,160,160,160,     2       210,220,230,240,250,260,270,900), JCC     BENDING MAGNET FIELD SECOND DERIVATIVEC   10 BDBI = PARAM      VARS(7) = NVARY      GO TO 900CC     FRINGING FIELD TRANSVERSE DISPLACEMENT INTEGRALC   20 LAYKI = PARAM      GO TO 900CC     PARTICLE MASSC   30 SM = PARAM*UNITI(10)      IF (RI .NE. 0.0 .AND. SM .NE. 0.0) THEN        E = SQRT(SM**2 + RI**2)        BETA = RI/E        GAMMA = E/SM      ENDIF      GO TO 900CC     BENDING MAGNET APERTURESC   40 APBI(J-3) = PARAM      GO TO 900CC     CUMULATIVE LENGTH OF SYSTEMC   60 LC = PARAM*UFLOOR(1)      IF (NV1 .GE. 1) THEN        DO 65 N = 1, NV1        LCV(N) = 0.0   65   CONTINUE      ENDIF      GO TO 900CC     FRINGING FIELD INTEGRALSC   70 LAYLI = PARAM      GO TO 900   80 LAYXI = PARAM      GO TO 900CC     JUNKC   90 RDL = PARAM      GO TO 900C  100 RDB = PARAM      GO TO 900CC     DESIGN MOMENTUMC  110 P = RI*(1.0 + CO(6))      RI = PARAM*UNITI(11)      CO(6) = P/RI - 1.0      IF (.NOT. LPRF) PREF = RI      SOFA = .TRUE.      RECENT = .FALSE.      GO TO 900CC     BENDING MAGNET ENTRANCE AND EXIT FACE CURVATURESC  120 RAB1I = PARAM      VARS(1) = NVARY      GO TO 900C  130 RAB2I = PARAM      VARS(2) = NVARY      GO TO 900CC     SEED FOR RANDOM NUMBER GENERATORC  140 CALL RANSET(ISEEDX)C     CALL RANSET(PARAM)      GO TO 900CC     TILT OF FOCAL PLANEC  150 FOTILT = PARAM      GO TO 900CC     FLOOR COORDINATES OF BEGINNING OF BEAMC  160 CALL FCSET      GO TO 900CC     REFERENCE MOMENTUM FOR WHICH MAGNETIC FIELDS ARE SETC  210 PREF = PARAM*UNITI(11)      LPRF = .TRUE.      GO TO 900CC     EXCESS FIELD OF A BENDING MAGNETC  220 RMPSI = PARAM      VARS(3) = NVARY      GO TO 900CC     MULTIPLICATAVE CONSTANT FOR NON-MIDPLANE-SYMMETRIC MULTIPOLESC  230 RNMSI = PARAM      VARS(4) = NVARY      GO TO 900CC     VERTICALLY BENDING FIELD OF A BENDING MAGNETC  240 VRNI = PARAM      VARS(5) = NVARY      GO TO 900CC     NORMALIZED MIDPLANE-ANTISYMMETRIC QUADRUPOLE COMPONENTC  250 NPNI = PARAM      VARS(6) = NVARY      GO TO 900CC     NORMALIZED MIDPLANE-ANTISYMMETRIC SEXTUPOLE COMPONENTC  260 BDBPI = PARAM      VARS(8) = NVARY      GO TO 900CC     BENDING MAGNET FIELD THIRD DERIVATIVEC  270 GAMI = PARAM      VARS(9) = NVARY      GO TO 900CC     UNDEFINED OPERATIONSC  900 RETURN      END